// GraphNodeEvalable
func (n *NodeValidatableResource) Execute(ctx EvalContext, op walkOperation) (diags tfdiags.Diagnostics) {
	if n.Config == nil {
		return diags.Append(n.validateImportTargets(ctx))
	}

	diags = diags.Append(n.validateResource(ctx))

	diags = diags.Append(n.validateCheckRules(ctx, n.Config))

	if managed := n.Config.Managed; managed != nil {
		// Validate all the provisioners
		for _, p := range managed.Provisioners {
			diags = diags.Append(n.validateProvisioner(ctx, p, n.Config.Managed.Connection))
			if diags.HasErrors() {
				return diags
			}
		}
	}

	diags = diags.Append(n.validateImportTargets(ctx))

	return diags
}

// validateImportTargets validates any import blocks which are attached to this
// resource, checking that the expressions within the import blocks can be
// evaluated in the current context.
func (n *NodeValidatableResource) validateImportTargets(ctx EvalContext) tfdiags.Diagnostics {
	var diags tfdiags.Diagnostics

	for _, imp := range n.importTargets {
		// legacy imports from the CLI have no configuration to validate
		if imp.Config == nil {
			continue
		}

		if imp.Config.ForEach == nil {
			traversal, hds := hcl.AbsTraversalForExpr(imp.Config.To)
			diags = diags.Append(hds)
			to, tds := addrs.ParseAbsResourceInstance(traversal)
			diags = diags.Append(tds)
			if diags.HasErrors() {
				return diags
			}

			_, evalDiags := evaluateImportIdExpression(imp.Config.ID, to, ctx, EvalDataForNoInstanceKey, true)
			diags = diags.Append(evalDiags)
			if diags.HasErrors() {
				return diags
			}
			continue
		}

		forEachData, known, forEachDiags := newForEachEvaluator(imp.Config.ForEach, ctx, true).ImportValues()
		diags = diags.Append(forEachDiags)
		if forEachDiags.HasErrors() {
			return diags
		}

		if !known {
			_, evalDiags := evalImportUnknownToExpression(imp.Config.To)
			diags = diags.Append(evalDiags)
			continue
		}

		for _, keyData := range forEachData {
			res, evalDiags := evalImportToExpression(imp.Config.To, keyData)
			diags = diags.Append(evalDiags)
			if evalDiags.HasErrors() {
				return diags
			}

			_, evalDiags = evaluateImportIdExpression(imp.Config.ID, res, ctx, keyData, true)
			diags = diags.Append(evalDiags)
			if evalDiags.HasErrors() {
				return diags
			}
		}
	}

	return diags
}

