package terraform

import (
	"testing"

	"github.com/hashicorp/terraform/internal/addrs"
	"github.com/hashicorp/terraform/internal/configs/configschema"
	"github.com/hashicorp/terraform/internal/providers"
)

func scratchNullProvider(t *testing.T) providers.Factory {
	p := testProvider("null")
	p.GetProviderSchemaResponse = getProviderSchemaResponseFromProviderSchema(&providerSchema{
		ResourceTypes: map[string]*configschema.Block{
			"null_resource": {
				Attributes: map[string]*configschema.Attribute{},
			},
		},
	})
	return testProviderFuncFixed(p)
}

func TestScratchValidateImportBlocks(t *testing.T) {
	m := testModule(t, "scratch-validate-import-blocks")
	ctx := testContext2(t, &ContextOpts{
		Providers: map[addrs.Provider]providers.Factory{
			addrs.NewDefaultProvider("null"): scratchNullProvider(t),
		},
	})
	diags := ctx.Validate(m, nil)
	if !diags.HasErrors() {
		t.Fatalf("expected errors, got none")
	}
	for _, d := range diags {
		desc := d.Description()
		t.Logf("diag: %s (%s)", desc.Summary, desc.Detail)
	}
}

func TestScratchValidateImportBlocksValid(t *testing.T) {
	m := testModule(t, "scratch-validate-import-ok")
	ctx := testContext2(t, &ContextOpts{
		Providers: map[addrs.Provider]providers.Factory{
			addrs.NewDefaultProvider("null"): scratchNullProvider(t),
		},
	})
	diags := ctx.Validate(m, nil)
	if diags.HasErrors() {
		for _, d := range diags {
			desc := d.Description()
			t.Logf("diag: %s (%s)", desc.Summary, desc.Detail)
		}
		t.Fatalf("unexpected errors")
	}
}
